import { assign, IS_NON_DIMENSIONAL } from '../util';
import options from '../options';

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	let i;

	for (i in oldProps) {
		if (i !== 'children' && i !== 'key' && !(i in newProps)) {
			setProperty(dom, i, null, oldProps[i], isSvg);
		}
	}

	for (i in newProps) {
		if (
			(!hydrate || typeof newProps[i] == 'function') &&
			i !== 'children' &&
			i !== 'key' &&
			i !== 'value' &&
			i !== 'checked' &&
			oldProps[i] !== newProps[i]
		) {
			setProperty(dom, i, newProps[i], oldProps[i], isSvg);
		}
	}
}

/**
 * Set a property value on a DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	let useCapture;
	let style;
	let styleKey;
	let styleKeys;
	let next;
	let unitless;
	let unitlessNames;
	let lower;
	let eventName;
	let lowerName;
	let handler;
	let shouldSetAttribute;

	o: if (name === 'style') {
		style = dom.style;
		if (typeof value == 'string') {
			style.cssText = value;
		} else {
			if (typeof oldValue == 'string') {
				style.cssText = oldValue = '';
			}

			styleKeys = {};
			if (oldValue) {
				if (typeof oldValue == 'object') {
					assign(styleKeys, oldValue);
				}
			}
			if (value) {
				if (typeof value == 'object') {
					assign(styleKeys, value);
				}
			}

			unitlessNames = null;
			for (styleKey in styleKeys) {
				if (value && typeof value == 'object' && styleKey in value) {
					if (!oldValue || value[styleKey] !== oldValue[styleKey]) {
						next = value[styleKey];
						if (styleKey[0] === '-') {
							style.setProperty(styleKey, next);
						} else if (next == null) {
							style[styleKey] = '';
						} else if (typeof next != 'number') {
							style[styleKey] = next;
						} else {
							unitless = false;
							if (unitlessNames == null) {
								unitlessNames = {
									'opacity': 1,
									'fillopacity': 1,
									'fill-opacity': 1,
									'strokeopacity': 1,
									'stroke-opacity': 1,
									'stopopacity': 1,
									'stop-opacity': 1,
									'floodopacity': 1,
									'flood-opacity': 1,
									'flex': 1,
									'flexgrow': 1,
									'flexshrink': 1,
									'flexpositive': 1,
									'flexnegative': 1,
									'boxflex': 1,
									'box-flex': 1,
									'boxflexgroup': 1,
									'fontweight': 1,
									'lineheight': 1,
									'lineclamp': 1,
									'gridarea': 1,
									'grid-area': 1,
									'gridrow': 1,
									'grid-row': 1,
									'gridrowstart': 1,
									'grid-row-start': 1,
									'gridrowend': 1,
									'grid-row-end': 1,
									'gridrowspan': 1,
									'grid-row-span': 1,
									'gridcolumn': 1,
