									'animationiterationcount': 1,
									'animation-iteration-count': 1,
									'zoom': 1,
									'zindex': 1,
									'z-index': 1,
									'webkitflex': 1,
									'webkitflexgrow': 1,
									'webkitflexshrink': 1,
