									'webkitstrokeopacity': 1,
									'webkitfontweight': 1,
									'webkitlineheight': 1,
									'webkitzindex': 1,
									'webkitzoom': 1,
									'mozfillopacity': 1,
									'mozfontweight': 1,
									'mozzindex': 1,
									'msfontweight': 1,
									'mslineheight': 1,
									'mszindex': 1,
									'webkitanimationiterationcount': 1,
									'mozanimationiterationcount': 1,
									'msanimationiterationcount': 1,
									'webkitgridarea': 1,
									'mozgridrow': 1,
									'mozgridcolumn': 1,
									'webkitgrid-row': 1,
									'webkitgrid-column': 1,
									'grid-template-areas': 1,
									'webkitgridgap': 1,
									'mozgridgap': 1,
									'msgridgap': 1
								};
							}
